// Interpreta el botón (ap/ed/re/es/ok), la respuesta con el texto editado o una pregunta sobre un caso.
const u = $input.first().json;
if (u.callback_query) {
  const cq = u.callback_query;
  const [pref, id] = String(cq.data || '').split(':');
  const mapa = { ap: 'aprobar', ed: 'editar', re: 'rechazar', es: 'escalar', ok: 'enviar_editado' };
  const accion = mapa[pref] || 'ignorar';
  return [{ json: { accion, respuesta_id: accion === 'escalar' ? null : id, escalamiento_id: accion === 'escalar' ? id : null, query_id: cq.id, chat_id: cq.message.chat.id } }];
}
const m = u.message;
if (!m || !m.text) return [];
const previo = String((m.reply_to_message && m.reply_to_message.text) || '');
const ref = previo.match(/ID: ([0-9a-f-]{36})/);
if (ref) {
  return [{ json: { accion: 'guardar_edicion', respuesta_id: ref[1], texto: m.text, query_id: null, chat_id: m.chat.id } }];
}
// Consulta: "caso 1050 ...", "#1050 ...", "1050 ...", "T11 ..." o respondiendo a un mensaje que trae "Caso #1050"
const txt = m.text.trim();
const num = txt.match(/(?:caso|#)\s*#?\s*(\d{3,7})/i) || txt.match(/^(\d{3,7})\b/) || previo.match(/Caso #(\d{3,7})/);
const tref = txt.match(/\b(T\d{2})\b/i);
const base = { pregunta: txt, chat_id: m.chat.id, query_id: null };
if (num) return [{ json: { ...base, accion: 'consultar', campo: 'numero_caso', valor: num[1] } }];
if (tref) return [{ json: { ...base, accion: 'consultar', campo: 'ticket_ref', valor: tref[1].toUpperCase() } }];
return [{ json: { ...base, accion: 'ayuda' } }];

// P5: responde sobre UN caso solo con la fila de v_caso_detalle (fechas en hora Bogotá).
const q = $('Interpretar acción').first().json;
const caso = $('Leer caso').first().json || {};
if (!caso.numero_caso) {
  return [{ json: { encontrado: false, chat_id: q.chat_id, valor: q.valor } }];
}
const hora = (iso) => iso ? DateTime.fromISO(String(iso)).setZone('America/Bogota').setLocale('es').toFormat("ccc d LLL yyyy, h:mm a") : null;
const datos = { ...caso };
for (const k of ['ticket_id', 'respuesta_id', 'escalamiento_id']) delete datos[k];
for (const k of Object.keys(datos)) if (k.endsWith('_at')) datos[k] = hora(datos[k]);
if (datos.incidente) {
  datos.incidente = { ...datos.incidente, detectado_at: hora(datos.incidente.detectado_at), inicio_at: hora(datos.incidente.inicio_at) };
}
if (Array.isArray(datos.correos)) datos.correos = datos.correos.map(c => ({ ...c, enviado_at: hora(c.enviado_at) }));
const p = $('Leer prompt P5').first().json;
return [{ json: {
  encontrado: true, chat_id: q.chat_id, numero_caso: caso.numero_caso, cliente: caso.cliente,
  // Para los botones y para mostrar el borrador pendiente tal cual (no lo reescribe la IA)
  respuesta_id: caso.respuesta_id || null, respuesta_estado: caso.respuesta_estado || null,
  respuesta_tipo: caso.respuesta_tipo || null, borrador: caso.texto_final || caso.borrador || '',
  escalamiento_id: caso.escalamiento_id || null, escalamiento_estado: caso.escalamiento_estado || null,
  body: { model: 'gpt-4o-mini', temperature: 0, messages: [
    { role: 'system', content: p.texto },
    { role: 'user', content: 'Pregunta del líder: ' + q.pregunta + '\n\nDatos del caso (JSON):\n' + JSON.stringify(datos) }
  ] }
} }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const corta = (s, n) => { s = String(s ?? ''); return s.length > n ? s.slice(0, n) + '…' : s; };
const a = $('Armar llamada P5').first().json;
const texto = $input.first().json.choices[0].message.content;
// ¿Qué botones lleva la respuesta? Solo los que aplican al estado actual del caso.
const respPendiente = !!a.respuesta_id && (a.respuesta_estado || 'pendiente') === 'pendiente';
const escAbierto = !!a.escalamiento_id && a.escalamiento_estado === 'abierto';
const botones = respPendiente && escAbierto ? 'resp_esc' : respPendiente ? 'resp' : escAbierto ? 'esc' : 'ninguno';
const esCom = a.respuesta_tipo === 'comunicado';
// El borrador pendiente se muestra TAL CUAL está guardado (no lo resume la IA)
const borrador = respPendiente && a.borrador
  ? '\n\n✍️ <b>' + (esCom ? 'Comunicado' : 'Respuesta') + ' pendiente de aprobación</b>\n<blockquote>' + esc(corta(a.borrador, 2000)) + '</blockquote>'
  : '';
const accion = respPendiente
  ? '\n👇 <b>Aprobar y enviar</b> manda este texto por correo al cliente. <b>Editar</b> te deja corregirlo antes (no se envía hasta que confirmes).' + (escAbierto ? ' <b>Confirmar escalamiento</b> manda la ficha a Ingeniería.' : '')
  : (escAbierto ? '\n\n👇 El escalamiento sigue abierto: <b>Confirmar escalamiento</b> manda la ficha a Ingeniería.' : '');
return [{ json: { chat_id: a.chat_id, botones, respuesta_id: a.respuesta_id, escalamiento_id: a.escalamiento_id,
  mensaje: '🔎 <b>Caso #' + esc(a.numero_caso) + '</b> · ' + esc(a.cliente) + '\n\n' + esc(texto) + borrador + accion + '\n\n<i>Responde a este mensaje para seguir preguntando por el caso.</i>' } }];

// Punto común para Aprobar y Editar: qué respuesta se envía y a qué chat se confirma.
const q = $('Interpretar acción').first().json;
return [{ json: { respuesta_id: q.respuesta_id, chat_id: q.chat_id, accion: q.accion } }];

// Correo al cliente con el texto final aprobado (o editado y confirmado). Modo demo: llega al buzón de prueba.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const q = $('Preparar envío al cliente').first().json;
const caso = $('Leer caso para correo').first().json;
const dest = Object.fromEntries($('Leer destinatarios (cliente)').all().map(i => [i.json.rol, i.json.correo]));
const esCom = caso.respuesta_tipo === 'comunicado';
const texto = caso.texto_final || caso.borrador || '';
const asunto = '[Caso #' + caso.numero_caso + '] ' + (esCom ? 'Comunicado' : 'Respuesta') + ' de Soporte · ' + caso.asunto;
const html = '<div style="font-family:Arial,sans-serif;font-size:14px;color:#222;max-width:640px">' +
  '<p style="color:#888;font-size:12px">DEMO · En producción este correo iría al contacto de ' + esc(caso.cliente) + ' registrado en el help desk.</p>' +
  '<p>' + esc(texto).replace(/\n/g, '<br>') + '</p>' +
  '<hr style="border:none;border-top:1px solid #ddd"><p style="color:#888;font-size:12px">Caso #' + caso.numero_caso + ' · ' + esc(caso.cliente) + ' (' + esc(caso.pais) + ') · ' +
  (q.accion === 'enviar_editado' ? 'Editado y aprobado' : 'Aprobado') + ' por el líder de soporte</p></div>';
return [{ json: { para: dest.cliente, destinatario_real: 'contacto de ' + caso.cliente + ' (help desk)', asunto, html,
  tipo: esCom ? 'comunicado_cliente' : 'respuesta_cliente', ticket_id: caso.ticket_id, numero_caso: caso.numero_caso,
  respuesta_id: q.respuesta_id, chat_id: q.chat_id, cliente: caso.cliente, es_comunicado: esCom } }];

