// Correo a Ingeniería con la ficha P3 y el contexto del caso.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const hora = (iso) => iso ? DateTime.fromISO(String(iso)).setZone('America/Bogota').setLocale('es').toFormat("ccc d LLL yyyy, h:mm a") : '';
const q = $('Interpretar acción').first().json;
const caso = $('Leer caso del escalamiento').first().json;
const dest = Object.fromEntries($('Leer destinatarios (Ingeniería)').all().map(i => [i.json.rol, i.json.correo]));
const ficha = caso.ficha && typeof caso.ficha === 'object' ? caso.ficha : {};
const etiqueta = (k) => k.replace(/_/g, ' ').replace(/^./, (c) => c.toUpperCase());
const valor = (v) => Array.isArray(v) ? '<ul>' + v.map(x => '<li>' + esc(typeof x === 'object' ? JSON.stringify(x) : x) + '</li>').join('') + '</ul>' : esc(typeof v === 'object' ? JSON.stringify(v) : v);
const filas = Object.entries(ficha).map(([k, v]) => '<tr><td style="padding:6px 10px;border:1px solid #ddd;font-weight:bold;vertical-align:top">' + esc(etiqueta(k)) + '</td><td style="padding:6px 10px;border:1px solid #ddd">' + valor(v) + '</td></tr>').join('');
const asunto = '[Escalamiento ' + caso.severidad + '] Caso #' + caso.numero_caso + ' · ' + (ficha.titulo || caso.asunto);
const html = '<div style="font-family:Arial,sans-serif;font-size:14px;color:#222;max-width:720px">' +
  '<p><b>Caso #' + caso.numero_caso + '</b> · ' + esc(caso.cliente) + ' (' + esc(caso.pais) + ') · ' + esc(caso.producto) + ' · ' + esc(caso.ambiente) + '<br>' +
  'Severidad: <b>' + esc(caso.severidad) + '</b> · Origen: ' + esc(caso.origen_falla) + ' · Recibido: ' + esc(hora(caso.recibido_at)) + ' (hora Bogotá)</p>' +
  '<p><b>Reporte del cliente</b><br>' + esc(caso.cuerpo).replace(/\n/g, '<br>') + '</p>' +
  '<p><b>Ficha de escalamiento</b></p><table style="border-collapse:collapse;font-size:13px">' + filas + '</table>' +
  '<p style="color:#888;font-size:12px">Escalamiento confirmado por el líder de soporte desde Telegram. DEMO: datos sintéticos.</p></div>';
return [{ json: { para: dest.ingenieria, asunto, html, ticket_id: caso.ticket_id, numero_caso: caso.numero_caso,
  escalamiento_id: q.escalamiento_id, chat_id: q.chat_id, cliente: caso.cliente, severidad: caso.severidad } }];

